using Microsoft.EntityFrameworkCore;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
namespace Society.Api;
public static class MetaTemplates {
 public static string[] Parameters(CommunicationTemplate template,Dictionary<string,string> variables){var provider=Regex.Matches(template.ProviderBody,@"\{\{(\d+)\}\}");var local=Regex.Matches(template.Body,@"\{\{\s*([^{}]+?)\s*\}\}");if(provider.Count!=local.Count||Regex.Replace(template.ProviderBody,@"\{\{\d+\}\}","{}").Trim()!=Regex.Replace(template.Body,@"\{\{\s*[^{}]+?\s*\}\}","{}").Trim())throw new DomainException("Local text must match the provider-approved template; map its variables only");var map=new Dictionary<int,string>();for(int i=0;i<provider.Count;i++){var index=int.Parse(provider[i].Groups[1].Value);if(index is <1 or >20)throw new DomainException("Unsupported WhatsApp parameter position");var name=local[i].Groups[1].Value;if(map.TryGetValue(index,out var prior)&&prior!=name)throw new DomainException("Repeated template positions must map consistently");map[index]=name;}if(map.Count>0&&map.Keys.Max()!=map.Count)throw new DomainException("Provider positions must be consecutive");return map.OrderBy(p=>p.Key).Select(p=>variables.GetValueOrDefault(p.Value,"")).ToArray();}
 public static async Task<int> Sync(AppDb db,CommunicationAccount account,CommunicationProviders providers,CancellationToken ct){var secret=providers.Secrets(account);JsonArray items;if(account.Provider=="Test"&&providers.MockAllowed)items=secret["templates"]?.AsArray()??[];else{if(account.Provider!="Meta"||!account.Verified)throw new DomainException("Verify a Meta account first");var version=secret["apiVersion"]?.ToString()??"";var waba=secret["wabaId"]?.ToString()??"";if(!Regex.IsMatch(version,@"^v\d+\.\d+$")||!Regex.IsMatch(waba,@"^\d+$"))throw new DomainException("Configure Graph version and WhatsApp Business Account ID");using var client=providers.Client();client.DefaultRequestHeaders.Authorization=new("Bearer",secret["token"]?.ToString());var uri="https://graph.facebook.com/"+version+"/"+waba+"/message_templates?fields=name,language,status,components&limit=100";using var response=await client.GetAsync(uri,ct);if(!response.IsSuccessStatusCode)throw new DomainException("Template synchronization was rejected by Meta");items=JsonNode.Parse(await response.Content.ReadAsStringAsync(ct))?["data"]?.AsArray()??[];}
 var count=0;foreach(var item in items){var name=item?["name"]?.ToString();var lang=item?["language"]?.ToString();if(string.IsNullOrEmpty(name)||string.IsNullOrEmpty(lang))continue;var components=item?["components"]?.AsArray()??[];var body=components.FirstOrDefault(c=>c?["type"]?.ToString()=="BODY")?["text"]?.ToString()??"";if(body=="")continue;var supported=!components.Any(c=>c?["type"]?.ToString()=="HEADER"&&(c?["format"]?.ToString()!="TEXT"||c?["text"]?.ToString().Contains("{{")==true));var template=await db.Set<CommunicationTemplate>().SingleOrDefaultAsync(t=>t.TenantId==account.TenantId&&t.Name==name&&t.Language==lang&&t.Channel=="WhatsApp",ct);if(template==null){template=new(){TenantId=account.TenantId,UnitId=account.UnitId,Name=name,Language=lang,Channel="WhatsApp",ProviderName=name};template.Body=Regex.Replace(body,@"\{\{(\d+)\}\}",m=>"{{"+CommunicationService.Variables[(int.Parse(m.Groups[1].Value)-1)%CommunicationService.Variables.Length]+"}}");db.Add(template);}template.ProviderBody=body;template.ProviderAccountId=account.Id;template.ProviderStatus=supported?item?["status"]?.ToString()??"UNKNOWN":"UNSUPPORTED_HEADER";count++;}await db.SaveChangesAsync(ct);return count;}
}
